use verus::prelude::*;

// A sequence is “happy” exactly when
//   1) it has length ≥ 3, and
//   2) every contiguous window of size 3 consists of pairwise‐distinct characters.
//
// We capture that specification in the two‐way ensures below.
#[verifier::requires(true)]
#[verifier::ensures(|res: bool|
    // When the function returns true, these two conditions hold:
    res
      <==>
    (
      s.len() >= 3
      &&
      // For all valid windows i..i+2, the three chars at i,i+1,i+2 are distinct
      forall |i: usize|
        ensures i + 2 < s.len() ==>
          s[i] != s[i+1]
          && s[i] != s[i+2]
          && s[i+1] != s[i+2]
    )
)]
#[verifier::ensures(|res: bool|
    // When it returns false, either length<3 or some window has a repetition
    !res
      <==>
    (
      s.len() < 3
      ||
      exists |i: usize|
        ensures i + 2 < s.len() &&
                (s[i] == s[i+1]
                 || s[i] == s[i+2]
                 || s[i+1] == s[i+2])
    )
)]
fn is_happy(s: Vec<char>) -> bool {
    // A sequence must have at least 3 characters to be "happy".
    if s.len() < 3 {
        return false;
    }

    // Check every contiguous block of 3 characters for pairwise distinctness.
    for window in s.windows(3) {
        if window[0] == window[1]
            || window[0] == window[2]
            || window[1] == window[2]
        {
            return false;
        }
    }

    true
}

